-- Asymmetric JWT signing keys with a lifecycle (Supabase's "JWT Signing Keys").
--
-- Better Auth's jwt plugin used to sign with whichever row was newest and never
-- retired one. Each key now carries its algorithm and where it is in the
-- rotation: standby -> in_use -> previously_used -> revoked.
ALTER TABLE "auth"."jwks"
  ADD COLUMN "alg"    TEXT,
  ADD COLUMN "crv"    TEXT,
  ADD COLUMN "status" TEXT NOT NULL DEFAULT 'standby';

-- Every existing key was generated by the plugin default, Ed25519. Without the
-- backfill a verifier would import it with whatever algorithm is now the default.
UPDATE "auth"."jwks" SET "alg" = 'EdDSA', "crv" = 'Ed25519' WHERE "alg" IS NULL;

-- The key Better Auth signed with (the newest) stays in use; any older ones had
-- already stopped signing but may still back live tokens.
UPDATE "auth"."jwks"
SET "status" = CASE
  WHEN "id" = (SELECT "id" FROM "auth"."jwks" ORDER BY "createdAt" DESC LIMIT 1) THEN 'in_use'
  ELSE 'previously_used'
END;

-- Exactly one key signs at a time. Rotation swaps the two rows in one
-- transaction; this is the backstop for two rotations racing each other.
CREATE UNIQUE INDEX "jwks_one_in_use" ON "auth"."jwks"("status") WHERE "status" = 'in_use';
